INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'A Day Full of the Unexpected', 'Last Saturday started as a normal day, but it was full of the unexpected. First, I overslept. By the time I woke up, it was already nine o''clock. I had planned to meet my friend at the station at nine. I jumped out of bed and got ready in a hurry. But when I got to the bus stop, the bus had already left. I had to wait for the next one. When I finally arrived at the station, my friend had gone home. I felt terrible. I had let her down. Then my phone rang. It was my friend. "Don''t worry," she said. "I overslept too! I just got here." We both laughed. What a day!', '记叙文', 117, '[{"q": "When did the writer wake up?", "answer": "C", "options": ["At seven.", "At ten.", "At nine o''clock.", "At eight."], "explanation": "原文:it was already nine o''clock"}, {"q": "Where was the writer supposed to meet the friend?", "answer": "B", "options": ["At school.", "At the station.", "At the bus stop.", "At home."], "explanation": "原文:meet my friend at the station"}, {"q": "What had happened when the writer got to the bus stop?", "answer": "C", "options": ["The friend came.", "The bus was waiting.", "The bus had already left.", "The bus broke down."], "explanation": "原文:the bus had already left"}, {"q": "How did the writer feel at the station?", "answer": "A", "options": ["Terrible.", "Happy.", "Calm.", "Excited."], "explanation": "原文:I felt terrible"}, {"q": "Why did they both laugh?", "answer": "C", "options": ["They missed the bus.", "They were late.", "The friend had overslept too.", "They went home."], "explanation": "原文:I overslept too"}]'::jsonb, '[{"word": "overslept", "cn": "睡过头(过去式)"}, {"word": "unexpected", "cn": "出乎意料的"}, {"word": "station", "cn": "车站"}]'::jsonb, 3, '9', 'U12');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'The Day the Aliens Came', 'On the night of October 30, 1938, something strange happened in the US. A radio show announced that aliens from Mars had landed on Earth. The show said the aliens were burning towns and killing people. Many people who were listening did not know it was just a play. They thought it was real news. People ran into the streets in fear. Some packed their things and tried to leave the city. The roads were full of cars. By the time people learned the truth, many had become very frightened. The show was actually a famous April Fool''s-style hoax. It taught everyone to be careful about what they hear.', '记叙文', 109, '[{"q": "When did the strange thing happen?", "answer": "A", "options": ["On October 30, 1938.", "In 1893.", "In 1983.", "In 2000."], "explanation": "原文:October 30, 1938"}, {"q": "What did the radio show announce?", "answer": "B", "options": ["A war had started.", "Aliens had landed on Earth.", "A storm was coming.", "A fire broke out."], "explanation": "原文:aliens from Mars had landed"}, {"q": "What did many listeners think?", "answer": "A", "options": ["It was real news.", "It was a joke.", "It was a song.", "It was an ad."], "explanation": "原文:They thought it was real news"}, {"q": "What did people do in fear?", "answer": "A", "options": ["Ran into the streets.", "Called friends.", "Went to sleep.", "Stayed calm."], "explanation": "原文:ran into the streets in fear"}, {"q": "What was the show actually?", "answer": "C", "options": ["A concert.", "Real news.", "A hoax.", "A weather report."], "explanation": "原文:a famous...hoax"}]'::jsonb, '[{"word": "announce", "cn": "宣布"}, {"word": "burn", "cn": "燃烧"}, {"word": "hoax", "cn": "骗局;恶作剧"}]'::jsonb, 3, '9', 'U12');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'An Embarrassing Costume Party', 'Last week, I was invited to a costume party. I was very excited. I spent a long time making a funny costume. On the day of the party, I put on my costume and went to my friend''s house. But when I got there, I was shocked. Everyone was wearing normal clothes! No one else had worn a costume. I stood at the door in disbelief. My friends stared at me. I felt so embarrassed. Then my friend laughed and said, "April Fool! There is no costume party. We just wanted to fool you!" By the time I understood, everyone was laughing. In the end, I laughed too. It was an embarrassing but fun day.', '记叙文', 115, '[{"q": "What was the writer invited to?", "answer": "D", "options": ["A concert.", "A wedding.", "A birthday party.", "A costume party."], "explanation": "原文:invited to a costume party"}, {"q": "What did the writer spend time making?", "answer": "C", "options": ["A gift.", "A card.", "A funny costume.", "A cake."], "explanation": "原文:making a funny costume"}, {"q": "What were others wearing at the party?", "answer": "B", "options": ["Costumes.", "Normal clothes.", "Uniforms.", "Sports clothes."], "explanation": "原文:wearing normal clothes"}, {"q": "How did the writer feel?", "answer": "D", "options": ["Proud.", "Calm.", "Happy.", "Embarrassed."], "explanation": "原文:I felt so embarrassed"}, {"q": "What was the truth?", "answer": "D", "options": ["The party was cancelled.", "The costume was wrong.", "Everyone was late.", "It was an April Fool''s joke."], "explanation": "原文:April Fool! ...wanted to fool you"}]'::jsonb, '[{"word": "costume", "cn": "服装;装束"}, {"word": "stare", "cn": "盯着看"}, {"word": "embarrassed", "cn": "窘迫的"}]'::jsonb, 3, '9', 'U12');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'The History of April Fool''s Day', 'April Fool''s Day is celebrated in many countries on April 1st. On this day, people play jokes on each other. The jokes are meant to be funny, not unkind. No one knows for sure how the day began. Some people think it started in France a long time ago. When the new year was moved to January 1st, some people did not know about the change. They still celebrated the new year on April 1st. Others began to fool them and call them "April fools". Today, people of all ages enjoy this day. Even newspapers and TV stations sometimes report funny fake stories. But by the end of the day, they tell everyone the truth.', '说明文', 115, '[{"q": "When is April Fool''s Day?", "answer": "A", "options": ["On April 1st.", "On January 1st.", "On October 30th.", "On April 30th."], "explanation": "原文:on April 1st"}, {"q": "What do people do on this day?", "answer": "C", "options": ["Sing songs.", "Have a feast.", "Play jokes on each other.", "Give gifts."], "explanation": "原文:play jokes on each other"}, {"q": "Where do some people think the day began?", "answer": "C", "options": ["In Italy.", "In China.", "In France.", "In the US."], "explanation": "原文:started in France"}, {"q": "Who were called April fools?", "answer": "A", "options": ["People who still celebrated the new year on April 1st.", "Children only.", "People who sang.", "People who gave gifts."], "explanation": "原文:call them April fools"}, {"q": "What do newspapers do by the end of the day?", "answer": "D", "options": ["Keep the joke going.", "Sell out.", "Cancel the news.", "Tell everyone the truth."], "explanation": "原文:they tell everyone the truth"}]'::jsonb, '[{"word": "celebrate", "cn": "庆祝"}, {"word": "fool", "cn": "愚弄;傻瓜"}, {"word": "fake", "cn": "假的"}]'::jsonb, 3, '9', 'U12');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'The Lost Backpack', 'It was a busy workday. Tom was in a hurry as usual. He grabbed his backpack and ran to catch the bus. By the time he got to the office, he was tired. He sat down and reached for his backpack. But it was not there! He realized he had left it on the bus. Inside were his keys, his phone, and some important papers. Tom was worried. He called the bus company. A kind lady there told him that a worker had found his backpack. "Don''t worry," she said. "It is safe here." Tom felt a great sense of relief. By the end of the day, he had got his backpack back. He learned to slow down and be more careful.', '记叙文', 122, '[{"q": "What kind of day was it?", "answer": "D", "options": ["A weekend.", "A school day.", "A holiday.", "A busy workday."], "explanation": "原文:a busy workday"}, {"q": "What did Tom leave on the bus?", "answer": "A", "options": ["His backpack.", "His coat.", "His lunch.", "His book."], "explanation": "原文:he had left it on the bus"}, {"q": "What was inside the backpack?", "answer": "A", "options": ["Keys, phone, and important papers.", "Toys.", "Food and water.", "Clothes."], "explanation": "原文:his keys, his phone, and some important papers"}, {"q": "Who found Tom''s backpack?", "answer": "B", "options": ["A police officer.", "A worker.", "A student.", "A teacher."], "explanation": "原文:a worker had found his backpack"}, {"q": "What did Tom learn?", "answer": "B", "options": ["To take a taxi.", "To slow down and be more careful.", "To buy a new bag.", "To run faster."], "explanation": "原文:slow down and be more careful"}]'::jsonb, '[{"word": "workday", "cn": "工作日"}, {"word": "backpack", "cn": "背包"}, {"word": "worker", "cn": "工人;工作者"}]'::jsonb, 3, '9', 'U12');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Notice: April Fool''s Day Fun', 'GREENWOOD SCHOOL — APRIL FOOL''S DAY! On April 1st, we will have a fun day at school. Here are the rules. KIND JOKES ONLY: You may play jokes on your friends, but they must be kind and safe. Do not hurt or scare anyone. COSTUME TIME: At lunch, you may wear a funny costume if you like. There will be a prize for the best one. NO MEAN TRICKS: Jokes that make others feel bad are not allowed. TELL THE TRUTH: By the end of the day, tell your friends the truth about any joke. Let''s make this a day full of laughter. Remember, the best jokes make everyone happy, not just the joker!', '应用文', 114, '[{"q": "When is the fun day at school?", "answer": "B", "options": ["On January 1st.", "On April 1st.", "On October 30th.", "On April 30th."], "explanation": "原文:On April 1st"}, {"q": "What kind of jokes are allowed?", "answer": "D", "options": ["Mean jokes.", "Scary jokes.", "No jokes.", "Kind and safe jokes."], "explanation": "原文:they must be kind and safe"}, {"q": "What can you do at lunch?", "answer": "C", "options": ["Play games.", "Eat free food.", "Wear a funny costume.", "Leave school."], "explanation": "原文:you may wear a funny costume"}, {"q": "What is not allowed?", "answer": "B", "options": ["Kind jokes.", "Jokes that make others feel bad.", "Costumes.", "Laughter."], "explanation": "原文:Jokes that make others feel bad are not allowed"}, {"q": "What should you do by the end of the day?", "answer": "D", "options": ["Leave early.", "Keep the joke.", "Win a prize.", "Tell your friends the truth."], "explanation": "原文:tell your friends the truth"}]'::jsonb, '[{"word": "costume", "cn": "服装"}, {"word": "fool", "cn": "愚弄"}, {"word": "prize", "cn": "奖品"}]'::jsonb, 3, '9', 'U12');
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U12', 'A Morning of Surprises', 'Last Saturday started as a normal day, but it was full of the (1)____. First, I (2)____. By the time I woke up, it was already nine. I had (3)____ to meet my friend at nine. I got ready in a (4)____. But when I got to the bus stop, the bus had already (5)____. I had to wait for the next (6)____. When I finally arrived, my friend (7)____ gone home. I felt (8)____. But then she called. "I overslept (9)____!" she said. We both (10)____. What an unexpected morning!', 91, 3, '[{"q": "1", "answer": "B", "options": ["game", "unexpected", "price", "color"], "explanation": "意外 unexpected"}, {"q": "2", "answer": "A", "options": ["overslept", "oversleeps", "oversleeping", "oversleep"], "explanation": "睡过头 overslept"}, {"q": "3", "answer": "B", "options": ["plan", "planned", "plans", "planning"], "explanation": "计划 had planned"}, {"q": "4", "answer": "A", "options": ["hurry", "color", "game", "price"], "explanation": "匆忙 in a hurry"}, {"q": "5", "answer": "B", "options": ["leaves", "left", "leave", "leaving"], "explanation": "离开 had left"}, {"q": "6", "answer": "D", "options": ["color", "price", "game", "one"], "explanation": "下一辆 the next one"}, {"q": "7", "answer": "A", "options": ["had", "did", "was", "have"], "explanation": "过完 had gone"}, {"q": "8", "answer": "C", "options": ["happy", "proud", "terrible", "glad"], "explanation": "糟糕 terrible"}, {"q": "9", "answer": "D", "options": ["so", "much", "very", "too"], "explanation": "也 too"}, {"q": "10", "answer": "C", "options": ["ran", "cried", "laughed", "slept"], "explanation": "笑 laughed"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U12', 'The Aliens Radio Show', 'On a night in 1938, something strange (1)____ in the US. A radio show (2)____ that aliens had landed on Earth. The show said the aliens were (3)____ towns. Many people who were (4)____ did not know it was just a (5)____. They thought it was (6)____ news. People ran into the (7)____ in fear. By the time they (8)____ the truth, many had become very (9)____. The show was a famous (10)____. It taught people to be careful about what they hear.', 83, 3, '[{"q": "1", "answer": "D", "options": ["happening", "happens", "happen", "happened"], "explanation": "发生 happened"}, {"q": "2", "answer": "D", "options": ["announce", "announces", "announcing", "announced"], "explanation": "宣布 announced"}, {"q": "3", "answer": "A", "options": ["burning", "color", "price", "game"], "explanation": "燃烧 burning"}, {"q": "4", "answer": "B", "options": ["price", "listening", "color", "game"], "explanation": "在听 listening"}, {"q": "5", "answer": "A", "options": ["play", "game", "color", "price"], "explanation": "戏剧 play"}, {"q": "6", "answer": "A", "options": ["real", "wrong", "bad", "false"], "explanation": "真实 real"}, {"q": "7", "answer": "B", "options": ["colors", "streets", "prices", "games"], "explanation": "街道 streets"}, {"q": "8", "answer": "C", "options": ["break", "throw", "learned", "lose"], "explanation": "得知 learned"}, {"q": "9", "answer": "B", "options": ["proud", "frightened", "happy", "glad"], "explanation": "害怕 frightened"}, {"q": "10", "answer": "C", "options": ["game", "price", "hoax", "color"], "explanation": "骗局 hoax"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U12', 'The Costume Party Joke', 'Last week, I was (1)____ to a costume party. I was very excited. I spent a long time (2)____ a funny costume. On the day, I (3)____ on my costume and went to my friend''s house. But when I got there, I was (4)____. Everyone was wearing (5)____ clothes! No one else had worn a (6)____. I stood at the door in (7)____. My friends (8)____ at me. I felt so (9)____. Then my friend said, "April (10)____!" There was no costume party. In the end, I laughed too.', 89, 3, '[{"q": "1", "answer": "D", "options": ["inviting", "invites", "invite", "invited"], "explanation": "被邀请 invited"}, {"q": "2", "answer": "A", "options": ["making", "lose", "throw", "break"], "explanation": "制作 making"}, {"q": "3", "answer": "B", "options": ["throw", "put", "break", "lose"], "explanation": "穿上 put on"}, {"q": "4", "answer": "A", "options": ["shocked", "proud", "happy", "glad"], "explanation": "震惊 shocked"}, {"q": "5", "answer": "D", "options": ["funny", "old", "new", "normal"], "explanation": "普通 normal"}, {"q": "6", "answer": "C", "options": ["color", "game", "costume", "price"], "explanation": "服装 costume"}, {"q": "7", "answer": "C", "options": ["price", "game", "disbelief", "color"], "explanation": "不信 disbelief"}, {"q": "8", "answer": "B", "options": ["throw", "stared", "break", "lose"], "explanation": "盯着 stared"}, {"q": "9", "answer": "B", "options": ["glad", "embarrassed", "happy", "proud"], "explanation": "窘迫 embarrassed"}, {"q": "10", "answer": "A", "options": ["Fool", "game", "price", "color"], "explanation": "April Fool 愚人节"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U12', 'About April Fool''s Day', 'April Fool''s Day is (1)____ in many countries on April 1st. On this day, people (2)____ jokes on each other. The jokes are meant to be (3)____, not unkind. No one knows for (4)____ how the day began. Some people think it (5)____ in France long ago. When the new year was (6)____ to January 1st, some people did not know about the (7)____. They still celebrated on April 1st. Others began to (8)____ them. Today, people of all (9)____ enjoy this day. But by the end of the day, they tell everyone the (10)____.', 95, 3, '[{"q": "1", "answer": "A", "options": ["celebrated", "celebrates", "celebrating", "celebrate"], "explanation": "庆祝 celebrated"}, {"q": "2", "answer": "B", "options": ["lose", "play", "throw", "break"], "explanation": "开玩笑 play jokes"}, {"q": "3", "answer": "A", "options": ["funny", "sad", "bad", "mean"], "explanation": "有趣 funny"}, {"q": "4", "answer": "C", "options": ["price", "game", "sure", "color"], "explanation": "确定 for sure"}, {"q": "5", "answer": "C", "options": ["starting", "start", "started", "starts"], "explanation": "开始 started"}, {"q": "6", "answer": "D", "options": ["moves", "moving", "move", "moved"], "explanation": "被移到 was moved"}, {"q": "7", "answer": "D", "options": ["price", "color", "game", "change"], "explanation": "变化 change"}, {"q": "8", "answer": "B", "options": ["throw", "fool", "break", "lose"], "explanation": "愚弄 fool"}, {"q": "9", "answer": "A", "options": ["ages", "prices", "colors", "games"], "explanation": "年龄 all ages"}, {"q": "10", "answer": "B", "options": ["game", "truth", "color", "price"], "explanation": "真相 truth"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U12', 'Tom''s Lost Backpack', 'It was a busy (1)____. Tom was in a hurry. He (2)____ his backpack and ran to catch the bus. By the time he got to the (3)____, he was tired. He reached for his backpack, but it was (4)____ there! He realized he had (5)____ it on the bus. Inside were his keys and some important (6)____. Tom was worried. He (7)____ the bus company. A kind (8)____ told him a worker had (9)____ his backpack. Tom felt a great sense of (10)____. By the end of the day, he had got it back.', 95, 3, '[{"q": "1", "answer": "A", "options": ["workday", "price", "game", "color"], "explanation": "工作日 workday"}, {"q": "2", "answer": "B", "options": ["throw", "grabbed", "break", "lose"], "explanation": "抓起 grabbed"}, {"q": "3", "answer": "A", "options": ["office", "color", "game", "price"], "explanation": "办公室 office"}, {"q": "4", "answer": "C", "options": ["very", "too", "not", "so"], "explanation": "不在 not there"}, {"q": "5", "answer": "B", "options": ["leaves", "left", "leave", "leaving"], "explanation": "落下 had left"}, {"q": "6", "answer": "D", "options": ["games", "colors", "prices", "papers"], "explanation": "文件 papers"}, {"q": "7", "answer": "D", "options": ["break", "throw", "lose", "called"], "explanation": "打电话 called"}, {"q": "8", "answer": "C", "options": ["game", "price", "lady", "color"], "explanation": "女士 lady"}, {"q": "9", "answer": "A", "options": ["found", "lose", "break", "throw"], "explanation": "找到 had found"}, {"q": "10", "answer": "B", "options": ["price", "relief", "game", "color"], "explanation": "轻松 relief"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U12', 'April Fool''s Day Rules', 'On April 1st, our school will have a fun (1)____. Here are the rules. You may (2)____ jokes on your friends, but they must be (3)____ and safe. Do not hurt or (4)____ anyone. At lunch, you may wear a funny (5)____. There will be a (6)____ for the best one. Jokes that make others feel (7)____ are not allowed. By the end of the day, tell your friends the (8)____ about any joke. Let''s make this a day full of (9)____. Remember, the best jokes make (10)____ happy, not just the joker!', 93, 3, '[{"q": "1", "answer": "D", "options": ["game", "color", "price", "day"], "explanation": "日子 day"}, {"q": "2", "answer": "A", "options": ["play", "throw", "break", "lose"], "explanation": "开玩笑 play jokes"}, {"q": "3", "answer": "C", "options": ["mean", "bad", "kind", "sad"], "explanation": "友善 kind"}, {"q": "4", "answer": "D", "options": ["lose", "break", "throw", "scare"], "explanation": "吓 scare"}, {"q": "5", "answer": "B", "options": ["game", "costume", "color", "price"], "explanation": "服装 costume"}, {"q": "6", "answer": "C", "options": ["game", "price", "prize", "color"], "explanation": "奖品 prize"}, {"q": "7", "answer": "B", "options": ["good", "bad", "kind", "glad"], "explanation": "难受 feel bad"}, {"q": "8", "answer": "B", "options": ["game", "truth", "price", "color"], "explanation": "真相 truth"}, {"q": "9", "answer": "A", "options": ["laughter", "price", "game", "color"], "explanation": "欢笑 laughter"}, {"q": "10", "answer": "A", "options": ["everyone", "price", "game", "color"], "explanation": "每个人 everyone"}]'::jsonb, 6);
