INSERT INTO public.junior_writing_prompts (id, grade, topic, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, difficulty, title_en, high_sentences, error_pairs, paragraph_template, volume, unit) SELECT gen_random_uuid(), 9, 'An Unexpected Day', '用过去完成时(had + 过去分词)写一篇短文,讲一件出乎意料的事(如睡过头、坐错车、被开玩笑)。用by the time/when等表达事情发生的先后。60词左右。', 'Write a short passage on the topic: "An Unexpected Day".', '["发生了什么意外的事", "用过去完成时说明先发生了什么(had done)", "你当时的感受", "结果如何"]'::jsonb, 70, 100, 'Last Monday was full of the unexpected. I overslept. By the time I woke up, it was already eight o''clock. I got ready in a hurry. But when I got to the bus stop, the bus had already left. I had to walk to school. By the time I arrived, the first class had started. I felt terrible. But my teacher was kind and let me in. In the end, I learned to set my alarm earlier.', 'content:含意外事件/先后顺序/感受/结果(4分)；language:正确使用过去完成时had+过去分词(3分)；structure:叙事清楚、衔接得当(2分)；wordcount:词数达标、书写规范(1分)', 3, 'An Unexpected Day', '["By the time I ...", "When I ..., I realized I had ...", "had already ...", "It was full of the unexpected.", "I felt ...", "In the end ..."]'::jsonb, '[]'::jsonb, '要点:发生了什么意外的事；用过去完成时说明先发生了什么(had done)；你当时的感受；结果如何', '9', 'U12' WHERE NOT EXISTS (SELECT 1 FROM public.junior_writing_prompts WHERE volume='9' AND unit='U12' AND topic='An Unexpected Day');
